import { useEffect, useRef, useState } from 'react';
import { draftHandoff, searchDemoPolicy, generateSpeech, initialVoice, preparedResult } from '../agents/handoff.js';
import ProviderChips from '../components/ProviderChips.jsx';
import InsuranceProfileForm from '../components/InsuranceProfileForm.jsx';
import { loadCapabilities, handoffProviders } from '../agents/providers.js';
import { PHONE_AGENT_URL } from '../config.js';

const POLICY_QUERY = 'accident deductible home visit';

// One step at a time: facts → German script → ready. Finished steps collapse to one line with Edit.
function Done({ label, onEdit }) {
  return <div className="substep-done"><span>✓ {label}</span><button className="btn ghost small" onClick={onEdit}>Edit</button></div>;
}

export default function LiveHandoff({ t, lang, target, clinic, context, rail, onDone, onRehearse }) {
  const [step, setStep] = useState('facts'); // facts | script | ready
  const [message, setMessage] = useState(context.summary || '');
  const [consent, setConsent] = useState(false);
  const [gradiumConsent, setGradiumConsent] = useState(false);
  const [voice, setVoice] = useState(() => initialVoice(context));
  const [script, setScript] = useState(null);
  const [evidence, setEvidence] = useState(null);
  const [query, setQuery] = useState(POLICY_QUERY);
  const [audio, setAudio] = useState('');
  const [error, setError] = useState('');
  const [busy, setBusy] = useState(false);
  const [caps, setCaps] = useState(null);
  const pending = useRef(null);
  useEffect(() => { let alive = true; loadCapabilities(PHONE_AGENT_URL || '').then(c => alive && setCaps(c)); return () => { alive = false; }; }, []);
  const audioRef = useRef('');
  useEffect(() => () => { pending.current?.abort(); if (audioRef.current) URL.revokeObjectURL(audioRef.current); }, []);
  async function run(task) {
    if (pending.current) return;
    const controller = new AbortController(); pending.current = controller;
    const timer = setTimeout(() => controller.abort(), 65000);
    setBusy(true); setError('');
    try { await task(controller.signal); }
    catch (e) { if (!controller.signal.aborted) setError(e.message); else setError('Request stopped or timed out. Retry explicitly.'); }
    finally { clearTimeout(timer); pending.current = null; setBusy(false); }
  }
  function clearAudio() {
    if (audioRef.current) URL.revokeObjectURL(audioRef.current);
    audioRef.current = ''; setAudio('');
  }
  const draft = () => run(async signal => {
    clearAudio(); setScript(null);
    setScript(await draftHandoff(message, lang, target, consent, signal));
    setStep('script');
    // The demo policy evidence is local and needs no sharing consent: fetch it once the facts are in.
    if (target === 'insurance' && !evidence) setEvidence(await searchDemoPolicy(POLICY_QUERY, signal).catch(() => null));
  });
  const speak = () => run(async signal => {
    clearAudio();
    const blob = await generateSpeech(script.lines.map(x => x.german).join('\n'), voice, gradiumConsent, signal);
    audioRef.current = URL.createObjectURL(blob); setAudio(audioRef.current);
    setStep('ready');
  });
  const callUrl = /^tel:\+[1-9]\d{6,14}$/.test(clinic?.callUrl || '') ? clinic.callUrl : null;
  const who = target === 'insurance' ? 'insurer' : 'vet';

  return <main className="plan handoff">
    {rail}
    <h1>Prepare the {who} conversation</h1>
    <p className="note">No call has been placed. No appointment or insurance coverage has been confirmed.</p>
    {clinic && <p>{clinic.name} · {clinic.phone || 'No published phone available'}</p>}

    {step === 'facts' ? <section className="card substep">
      <h2>1 · What should the {who} know?</h2>
      {target === 'insurance' && <InsuranceProfileForm />}
      <label>Facts and questions<textarea aria-label="Facts and questions" value={message} maxLength={4000} onChange={e => { setMessage(e.target.value); setScript(null); clearAudio(); }} /></label>
      <label><input type="checkbox" checked={consent} onChange={e => setConsent(e.target.checked)} /> Share these facts with Gemini to draft a German script with subtitles.</label>
      <button className="btn primary" disabled={busy || !consent || !message.trim()} onClick={draft}>Draft German script</button>
    </section> : <Done label="Facts" onEdit={() => setStep('facts')} />}

    {step === 'script' && script && <section className="card substep">
      <h2>2 · Review the German script</h2>
      {script.lines.map((line, i) => <div key={i}><p lang="de">{line.german}</p><p>{line.subtitle}</p></div>)}
      <label>Speech voice <select value={voice} onChange={e => { setVoice(e.target.value); clearAudio(); }}><option value="my_voice">My approved voice</option><option value="standard">Standard German voice</option></select></label>
      {voice === 'my_voice' && context.voice !== 'my_voice' && <p className="muted">No own German voice is ready yet. Set it up once under “Demo &amp; voice settings” on the home screen, or use the standard voice.</p>}
      <label><input type="checkbox" checked={gradiumConsent} onChange={e => setGradiumConsent(e.target.checked)} /> I reviewed the script and agree to share it with Gradium using the selected voice.</label>
      <button className="btn primary" disabled={busy || !gradiumConsent} onClick={speak}>Make audio</button>
      <button className="btn ghost" disabled={busy} onClick={() => setStep('ready')}>Skip audio</button>
    </section>}
    {step === 'ready' && script && <Done label={`German script · ${script.lines.length} lines`} onEdit={() => setStep('script')} />}

    {step === 'ready' && <section className="card substep">
      <h2>3 · Ready</h2>
      {audio ? <><audio controls src={audio} /><a href={audio} download="pawse-reviewed-script.wav">Download audio</a></> : <p className="muted">No audio made. You can read the script yourself.</p>}
      {callUrl && <p>Open your device dialer for {clinic.name}. Pawse cannot join or speak into this call. <a className="btn soft" href={callUrl}>Open dialer: {clinic.phone}</a></p>}
      <button className="btn primary" onClick={() => onDone(preparedResult(target, script, audio))}>Done, back to plan</button>
    </section>}

    {target === 'insurance' && step !== 'facts' && <section className="card">
      <h2>Demo policy, not your coverage</h2>
      {evidence ? evidence.evidence.map(e => <article key={e.evidence_id}><h3>{e.title} · {e.section}</h3><p style={{ whiteSpace: 'pre-wrap' }}>{e.snippet}</p><small>{e.source_id}</small></article>) : <p className="muted">No demo policy clauses loaded.</p>}
      <details>
        <summary>Ask another policy question</summary>
        <input aria-label="Demo policy question in English" value={query} maxLength={1000} onChange={e => setQuery(e.target.value)} />
        <button className="btn soft" disabled={busy || !query.trim()} onClick={() => run(async signal => setEvidence(await searchDemoPolicy(query, signal)))}>Search the demo policy</button>
      </details>
    </section>}

    {busy && <p role="status">Preparing…</p>}{error && <p role="alert">{error}</p>}
    <ProviderChips t={t} items={handoffProviders({ caps, voice, audioReady: !!audio, target })} />
    <details className="handoff-more">
      <summary>More</summary>
      {onRehearse && <button className="btn soft" onClick={onRehearse}>Open simulated Mimi phone rehearsal</button>}
      <button className="btn ghost" onClick={() => onDone(null)}>Back to care summary</button>
    </details>
  </main>;
}
import { IS_LIVE_PHONE } from '../agents/index.js';
import { nextAction } from '../utils/steps.js';
// Pawse's advice + the two "let Pawse call for you" actions.
// Used as the bottom sheet on the video call and at the top of the plan page.

const GLYPH = { red: '!', yellow: '◷', green: '✓' };

function ActionRow({ icon, title, sub, doneText, button, next, onClick }) {
  return (
    <div className={doneText ? 'action-row done' : 'action-row'}>
      <span className="action-icon" aria-hidden="true">{icon}</span>
      <div className="action-text">
        <strong>{title}</strong>
        <span>{doneText || sub}</span>
      </div>
      <button type="button" className={next ? 'btn primary small' : 'btn soft small'} onClick={onClick}>
        {button}
      </button>
    </div>
  );
}

export default function PlanPanel({ t, triage, vet, insurance, onCall }) {
  if (!triage) return null;
  // A live "prepared" result is only a script; it never reads as a booking or a confirmed cover.
  const vetDone = vet ? (vet.prepared ? `✓ ${t.prepared}` : `✓ ${t.booked} ${vet.time} · ≈ ${vet.currency || 'CHF'} ${vet.estimate}`) : '';
  const insDone = insurance ? (insurance.prepared ? `✓ ${t.prepared}` : `✓ ${t.outOfPocket} ≈ ${insurance.currency || 'CHF'} ${insurance.outOfPocket}`) : '';
  const next = nextAction({ vet, insurance });

  return (
    <div className="plan-panel">
      <div className={`level level-${triage.level}`}>
        <span className="level-glyph" aria-hidden="true">{GLYPH[triage.level]}</span>
        <div>
          <span className="level-kicker">{t.adviceTitle}</span>
          <strong className="level-title">{triage.headline || t.levels[triage.level]}</strong>
        </div>
      </div>

      <section>
        <h3>{t.nowDo}</h3>
        <ul className="steps">
          {triage.steps.map((s, i) => (
            <li key={i}>{s}</li>
          ))}
        </ul>
        {triage.escalation && <p className="escalation">{triage.escalation}</p>}
      </section>

      <section>
        <h3>{IS_LIVE_PHONE ? 'Prepare your next conversation' : t.transferTitle}</h3>
        <div className="actions">
          <ActionRow
            icon={t.callees.vet.icon}
            title={IS_LIVE_PHONE ? 'Prepare vet conversation' : t.callVet}
            sub={IS_LIVE_PHONE ? 'Review a German script and audio; no automatic call' : t.callVetSub}
            doneText={vetDone}
            next={next === 'vet'}
            button={vet ? t.callAgain : IS_LIVE_PHONE ? t.prepare : t.call}
            onClick={() => onCall('vet')}
          />
          <ActionRow
            icon={t.callees.insurance.icon}
            title={IS_LIVE_PHONE ? 'Prepare insurer conversation' : t.callIns}
            sub={IS_LIVE_PHONE ? 'Demo policy evidence and a script; coverage unconfirmed' : t.callInsSub}
            doneText={insDone}
            next={next === 'insurance'}
            button={insurance ? t.callAgain : IS_LIVE_PHONE ? t.prepare : t.call}
            onClick={() => onCall('insurance')}
          />
        </div>
        <p className="ai-note">{IS_LIVE_PHONE ? 'Review the script before sharing. Audio playback does not place a call.' : t.aiNote}</p>
      </section>
    </div>
  );
}
// Where the owner is in the story: 1 Talk · 2 Vet · 3 Insurance · 4 Summary.
export default function StepRail({ t, steps }) {
  const at = steps.findIndex((s) => s.current);
  return (
    <nav className="step-rail" aria-label={t.stepOf(at + 1, steps.length)}>
      <ol>
        {steps.map((s, i) => (
          <li key={s.id} className={s.done ? 'done' : s.current ? 'current' : ''} aria-current={s.current ? 'step' : undefined}>
            <span className="step-dot" aria-hidden="true">{s.done ? '✓' : i + 1}</span>
            <span className="step-name">{t.rail[s.id]}</span>
          </li>
        ))}
      </ol>
    </nav>
  );
}
import Avatar from '../components/Avatar.jsx';
import Icon from '../components/Icon.jsx';
import InsuranceProfileForm from '../components/InsuranceProfileForm.jsx';

const PETALS = [
  { left: '8%', delay: '0s', dur: '11s', size: 12 },
  { left: '24%', delay: '3s', dur: '13s', size: 9 },
  { left: '46%', delay: '6s', dur: '12s', size: 14 },
  { left: '67%', delay: '1.5s', dur: '14s', size: 10 },
  { left: '84%', delay: '4.5s', dur: '10s', size: 13 },
];

export default function Home({ t, lang, setLang, onStart, onOwnVoice }) {
  return (
    <main className="home">
      <div className="petals" aria-hidden="true">
        {PETALS.map((p, i) => (
          <span
            key={i}
            className="petal"
            style={{ left: p.left, animationDelay: p.delay, animationDuration: p.dur, width: p.size, height: p.size }}
          />
        ))}
      </div>

      <header className="topbar">
        <span className="brand">{t.appName}</span>
        <div className="lang-switch" role="group" aria-label="Language">
          {['en', 'zh', 'de', 'hi'].map((l) => (
            <button
              key={l}
              type="button"
              className={l === lang ? 'chip on' : 'chip'}
              aria-pressed={l === lang}
              onClick={() => setLang(l)}
            >
              {({zh:'中文',en:'EN',de:'DE',hi:'हिन्दी'})[l]}
            </button>
          ))}
        </div>
      </header>

      <section className="home-hero">
        <div className="home-avatar">
          <Avatar size={150} />
        </div>
        <h1>
          {t.tagline.split('\n').map((line, i) => (
            <span key={i}>{line}</span>
          ))}
        </h1>
        <button type="button" className="start-btn" onClick={onStart}>
          <Icon name="phone" size={24} />
          {t.startCall}
        </button>
        <p className="muted">{t.startHint}</p>
        <details className="home-settings">
          <summary>{t.settings}</summary>
          <button className="btn soft" onClick={onOwnVoice}>Record my voice · emergency rehearsal</button>
          <p><a href="?live=1">Use backend agents</a> · <a href="?demo=1">Simulated rehearsal</a></p>
        </details>
      </section>

      <InsuranceProfileForm />

      <footer className="disclaimer">{t.disclaimer}</footer>
    </main>
  );
}

